import { useState } from 'react'
import { Link } from 'react-router-dom'
import { fetchCertificateHtml } from '../../lib/data/bookings'
import { openHtmlInNewTab } from '../../lib/download'
import { formatManilaDate } from '../../lib/domain'
import type { BookingRegisterEntry } from '../../lib/types'
import { RegisterStatusBadge } from '../register/registerLabels'

/**
 * Completing a booking writes its parish register entry; the certificate is printed from that
 * entry. Nothing is generated by hand any more, so this card only shows it and links to it.
 */
export function RegisterEntryCard({ bookingId, entry }: { bookingId: string; entry: BookingRegisterEntry }) {
  const [error, setError] = useState<string | null>(null)

  async function viewCertificate() {
    setError(null)
    try {
      openHtmlInNewTab(await fetchCertificateHtml(bookingId))
    } catch (e) {
      setError((e as Error).message)
    }
  }

  return (
    <section aria-label="Register entry" className="rounded-2xl border border-line bg-surface px-6 py-[18px]">
      <h2 className="mb-3 font-display text-[20px] font-semibold text-navy">Register entry</h2>
      <div className="flex flex-wrap items-center gap-3">
        <p className="font-mono text-sm font-semibold text-ink">{entry.registerNumber}</p>
        <RegisterStatusBadge status={entry.status} />
      </div>
      <p className="mt-1 text-label text-ink-muted">Entered {formatManilaDate(entry.enteredAt)}</p>
      {error && <p className="mt-2 text-sm text-danger">{error}</p>}
      <div className="mt-3 flex flex-wrap gap-2">
        <button type="button" onClick={viewCertificate} className="rounded-full border border-navy px-4 py-2 text-sm font-semibold text-navy min-h-11 lg:min-h-9">
          View certificate
        </button>
        <Link to={`/register/${entry.id}`} className="rounded-full px-4 py-2 text-sm font-semibold text-navy underline">
          Open in register
        </Link>
      </div>
    </section>
  )
}
